CREATE VIEW v_order_totals AS SELECT order_id,sum(quantity*unit_price_cents) order_cents FROM order_lines GROUP BY order_id;
CREATE VIEW v_shipment_totals AS SELECT s.order_id,count(DISTINCT s.shipment_id) shipment_count,min(s.ship_date) first_ship_date,max(s.ship_date) last_ship_date,sum(sl.quantity*ol.unit_price_cents) shipped_cents FROM shipments s JOIN shipment_lines sl USING(shipment_id) JOIN order_lines ol ON ol.order_id=sl.order_id AND ol.line_no=sl.line_ref GROUP BY s.order_id;
CREATE VIEW v_gl_invoice AS SELECT j.invoice_id,sum(CASE WHEN l.account_id='1100' THEN l.debit_cents-l.credit_cents ELSE 0 END) gl_ar_cents,sum(CASE WHEN l.account_id='4000' THEN l.credit_cents-l.debit_cents ELSE 0 END) gl_revenue_cents,min(j.posting_date) posting_date FROM journal_entries j JOIN journal_lines l USING(journal_id) WHERE j.source_type='invoice' GROUP BY j.invoice_id;
CREATE VIEW v_invoice_evidence AS
 SELECT i.*,o.customer_id,o.branch_id,o.order_date,t.order_cents,s.shipment_count,s.first_ship_date,s.last_ship_date,coalesce(s.shipped_cents,0) shipped_cents,
 coalesce((SELECT sum(quantity*unit_price_cents) FROM invoice_lines il WHERE il.invoice_id=i.invoice_id),0) line_cents,
 coalesce(g.gl_ar_cents,0) gl_ar_cents,coalesce(g.gl_revenue_cents,0) gl_revenue_cents,g.posting_date,
 row_number() OVER(PARTITION BY i.order_id,i.amount_cents ORDER BY i.invoice_id) repeated_rank
 FROM invoices i JOIN orders o USING(order_id) JOIN v_order_totals t USING(order_id) LEFT JOIN v_shipment_totals s USING(order_id) LEFT JOIN v_gl_invoice g USING(invoice_id);
CREATE VIEW v_manual_evidence AS SELECT j.*,coalesce((SELECT sum(debit_cents) FROM journal_lines l WHERE l.journal_id=j.journal_id),0) amount_cents,
 EXISTS(SELECT 1 FROM employee_roles er JOIN permissions p USING(role_id) WHERE er.employee_id=j.prepared_by AND p.action='post_manual') authorized,
 EXISTS(SELECT 1 FROM approvals a JOIN employee_roles er ON er.employee_id=a.approved_by JOIN permissions p USING(role_id) WHERE a.journal_id=j.journal_id AND a.status='approved' AND a.approved_by<>j.prepared_by AND p.action='approve_manual' AND a.approval_date<=j.posting_date) valid_approval
 FROM journal_entries j WHERE manual=1;
CREATE VIEW v_permission_conflicts AS SELECT e.employee_id,e.name FROM employees e WHERE EXISTS(SELECT 1 FROM employee_roles er JOIN permissions p USING(role_id) WHERE er.employee_id=e.employee_id AND p.action='create_invoice') AND EXISTS(SELECT 1 FROM employee_roles er JOIN permissions p USING(role_id) WHERE er.employee_id=e.employee_id AND p.action='apply_cash');
CREATE VIEW v_exception_core AS
 SELECT 'DUPLICATE' rule_id,'INV:'||invoice_id risk_key,invoice_id,NULL journal_id,customer_id,branch_id,recognition_date event_date,amount_cents flagged_value_cents,amount_cents exposure_cents,0 discrepancy_cents,'Order '||order_id||'; repeated rank '||repeated_rank evidence FROM v_invoice_evidence WHERE repeated_rank>1
 UNION ALL SELECT 'NO_SHIPMENT','INV:'||invoice_id,invoice_id,NULL,customer_id,branch_id,recognition_date,amount_cents,amount_cents,0,'Order '||order_id||'; no shipment lines found' FROM v_invoice_evidence WHERE shipment_count IS NULL
 UNION ALL SELECT 'EARLY_REVENUE','INV:'||invoice_id,invoice_id,NULL,customer_id,branch_id,recognition_date,amount_cents,amount_cents,0,'Recognized '||recognition_date||'; last shipment '||last_ship_date FROM v_invoice_evidence WHERE recognition_date<last_ship_date
 UNION ALL SELECT 'WRONG_PERIOD','INV:'||invoice_id,invoice_id,NULL,customer_id,branch_id,recognition_date,amount_cents,amount_cents,0,'Ship '||last_ship_date||'; recognized '||recognition_date||'; posted '||posting_date FROM v_invoice_evidence WHERE substr(recognition_date,1,7)<>substr(last_ship_date,1,7) OR substr(posting_date,1,7)<>substr(recognition_date,1,7)
 UNION ALL SELECT 'AMOUNT_MISMATCH','INV:'||invoice_id,invoice_id,NULL,customer_id,branch_id,recognition_date,amount_cents,max(abs(amount_cents-order_cents),abs(amount_cents-line_cents),abs(amount_cents-shipped_cents),abs(amount_cents-gl_ar_cents),abs(amount_cents-gl_revenue_cents)),max(abs(amount_cents-order_cents),abs(amount_cents-line_cents),abs(amount_cents-shipped_cents),abs(amount_cents-gl_ar_cents),abs(amount_cents-gl_revenue_cents)),
 'Order='||order_cents||'; invoice='||amount_cents||'; lines='||line_cents||'; shipped='||shipped_cents||'; GL AR='||gl_ar_cents||'; GL revenue='||gl_revenue_cents||' cents' FROM v_invoice_evidence WHERE shipment_count IS NOT NULL AND (amount_cents<>order_cents OR amount_cents<>line_cents OR amount_cents<>shipped_cents OR amount_cents<>gl_ar_cents OR amount_cents<>gl_revenue_cents)
 UNION ALL SELECT 'MANUAL_UNAUTHORIZED','JE:'||journal_id,NULL,journal_id,NULL,branch_id,posting_date,amount_cents,amount_cents,0,'Preparer employee '||prepared_by||' lacks post_manual permission' FROM v_manual_evidence WHERE authorized=0
 UNION ALL SELECT 'APPROVAL_FAILURE','JE:'||journal_id,NULL,journal_id,NULL,branch_id,posting_date,amount_cents,amount_cents,0,'Missing independent authorized approval on/before posting; preparer='||prepared_by FROM v_manual_evidence WHERE valid_approval=0
 UNION ALL SELECT 'SOD','INV:'||i.invoice_id,i.invoice_id,NULL,o.customer_id,o.branch_id,i.invoice_date,i.amount_cents,0,0,'Employee '||l.employee_id||' created invoice and applied cash; conflicting permissions' FROM invoices i JOIN orders o USING(order_id) JOIN activity_logs l ON l.invoice_id=i.invoice_id AND l.action='apply_cash' AND l.employee_id=i.created_by JOIN v_permission_conflicts c ON c.employee_id=l.employee_id GROUP BY i.invoice_id
 UNION ALL SELECT 'CASH_OVERALLOCATED','PAY:'||p.payment_id,a.invoice_id,NULL,o.customer_id,o.branch_id,a.allocation_date,p.amount_cents,(SELECT sum(amount_cents) FROM allocations b WHERE b.payment_id=p.payment_id)-p.amount_cents,(SELECT sum(amount_cents) FROM allocations b WHERE b.payment_id=p.payment_id)-p.amount_cents,'Payment '||p.payment_id||'; applied more than receipt' FROM payments p JOIN allocations a USING(payment_id) JOIN invoices i USING(invoice_id) JOIN orders o USING(order_id) WHERE (SELECT sum(amount_cents) FROM allocations b WHERE b.payment_id=p.payment_id)>p.amount_cents
 UNION ALL SELECT 'CASH_CUSTOMER','PAY:'||p.payment_id,a.invoice_id,NULL,o.customer_id,o.branch_id,a.allocation_date,p.amount_cents,(SELECT sum(ax.amount_cents) FROM allocations ax JOIN invoices ix ON ix.invoice_id=ax.invoice_id JOIN orders ox ON ox.order_id=ix.order_id WHERE ax.payment_id=p.payment_id AND ox.customer_id<>p.customer_id),0,'Payment '||p.payment_id||'; remitter='||p.customer_id||'; invoice customer='||o.customer_id FROM allocations a JOIN payments p USING(payment_id) JOIN invoices i USING(invoice_id) JOIN orders o USING(order_id) WHERE p.customer_id<>o.customer_id
 UNION ALL SELECT 'CASH_TIMING','PAY:'||p.payment_id,a.invoice_id,NULL,o.customer_id,o.branch_id,a.allocation_date,p.amount_cents,(SELECT sum(ax.amount_cents) FROM allocations ax JOIN invoices ix ON ix.invoice_id=ax.invoice_id WHERE ax.payment_id=p.payment_id AND (ax.allocation_date<p.payment_date OR ax.allocation_date<ix.recognition_date)),0,'Payment '||p.payment_id||'; received '||p.payment_date||'; applied '||a.allocation_date FROM allocations a JOIN payments p USING(payment_id) JOIN invoices i USING(invoice_id) JOIN orders o USING(order_id) WHERE a.allocation_date<p.payment_date OR a.allocation_date<i.recognition_date
 UNION ALL SELECT 'CREDIT_EXCESS','INV:'||i.invoice_id,i.invoice_id,NULL,o.customer_id,o.branch_id,max(c.credit_date),i.amount_cents,sum(c.amount_cents)-i.amount_cents,sum(c.amount_cents)-i.amount_cents,'Cumulative credits exceed original invoice; review return authorization' FROM credit_memos c JOIN invoices i USING(invoice_id) JOIN orders o USING(order_id) GROUP BY i.invoice_id HAVING sum(c.amount_cents)>i.amount_cents;
CREATE VIEW v_exceptions AS SELECT row_number() OVER(ORDER BY c.rule_id,c.risk_key,c.event_date) exception_id,c.*,i.invoice_no,i.order_id,i.invoice_date,i.due_date,i.recognition_date,
 (SELECT max(ship_date) FROM shipments s WHERE s.order_id=i.order_id) last_ship_date,
 (SELECT min(posting_date) FROM journal_entries j WHERE j.invoice_id=i.invoice_id AND j.source_type='invoice') gl_posting_date
 FROM v_exception_core c LEFT JOIN invoices i ON i.invoice_id=c.invoice_id;
CREATE VIEW v_line_issues AS
 SELECT i.invoice_id FROM invoices i JOIN invoice_lines il USING(invoice_id) JOIN order_lines ol ON ol.order_id=il.order_id AND ol.line_no=il.line_ref WHERE il.order_id<>i.order_id OR il.quantity<>ol.quantity OR il.unit_price_cents<>ol.unit_price_cents
 UNION SELECT i.invoice_id FROM invoices i WHERE EXISTS(SELECT 1 FROM order_lines ol WHERE ol.order_id=i.order_id AND NOT EXISTS(SELECT 1 FROM invoice_lines il WHERE il.invoice_id=i.invoice_id AND il.order_id=ol.order_id AND il.line_ref=ol.line_no))
 UNION SELECT i.invoice_id FROM invoices i JOIN order_lines ol ON ol.order_id=i.order_id WHERE EXISTS(SELECT 1 FROM shipments s WHERE s.order_id=i.order_id) AND ol.quantity<>coalesce((SELECT sum(sl.quantity) FROM shipment_lines sl JOIN shipments s USING(shipment_id) WHERE sl.order_id=ol.order_id AND sl.line_ref=ol.line_no AND s.order_id=i.order_id),0);
-- Additional line checks are exposed separately for operational completeness.
CREATE VIEW v_credit_support_issues AS SELECT c.* FROM credit_memos c LEFT JOIN returns r USING(return_id) WHERE r.return_id IS NULL OR r.invoice_id<>c.invoice_id OR c.credit_date<r.return_date OR c.amount_cents>r.amount_cents;
